CREATE TABLE IF NOT EXISTS Employee(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,salary DECIMAL(15,2) NOT NULL,created_Date DATETIME);
CREATE TABLE IF NOT EXISTS user_audit(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,action_name VARCHAR(50) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
